package rentivo_backend.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import rentivo_backend.dto.AuthDtos.*; import rentivo_backend.entity.*; import rentivo_backend.repository.*; import rentivo_backend.security.JwtService; import java.time.LocalDateTime;
@Service public class AuthService { private final UserRepository users; private final OtpChallengeRepository otps; private final JwtService jwt; private final String devCode; private final long otpMinutes;
 public AuthService(UserRepository u,OtpChallengeRepository o,JwtService j,@Value("${rentivo.otp.dev-code:123456}")String d,@Value("${rentivo.otp.expiration-minutes:5}")long m){users=u;otps=o;jwt=j;devCode=d;otpMinutes=m;}
 public SendOtpResponse sendOtp(String phone){phone=normalize(phone); if(phone==null)throw new IllegalArgumentException("Valid 10-15 digit mobile number is required"); OtpChallenge c=new OtpChallenge();c.setPhone(phone);c.setCode(devCode);c.setExpiresAt(LocalDateTime.now().plusMinutes(otpMinutes));otps.save(c); return new SendOtpResponse("OTP sent. Configure an SMS provider for production delivery.",devCode);}
 @Transactional public AuthResponse verify(VerifyOtpRequest req){String phone=normalize(req.phone()); OtpChallenge c=otps.findTopByPhoneAndUsedFalseOrderByIdDesc(phone).orElseThrow(()->new IllegalStateException("OTP not requested")); if(c.getExpiresAt().isBefore(LocalDateTime.now())||!c.getCode().equals(req.code()))throw new IllegalStateException("Invalid or expired OTP"); c.setUsed(true);otps.save(c); User u=users.findByPhone(phone).orElseGet(User::new); if(u.getId()==null){u.setPhone(phone);u.setRole(User.Role.USER);u.setActive(true);} u.setName(req.name()==null||req.name().isBlank()?"User":req.name().trim());u.setPhoneVerified(true);users.save(u); return new AuthResponse(jwt.generate(u.getId(),u.getPhone(),u.getRole().name()),u.getId(),u.getName(),u.getPhone(),u.getRole().name());}
 private String normalize(String p){if(p==null)return null; String x=p.replaceAll("\\s+",""); return x.matches("\\d{10,15}")?x:null;}
}
